from datetime import date, timedelta

class Loyalty:
    def __init__(self) -> None:
        self.customers = {}

    def purchase(self, customer: str, amount: float, day: date) -> int:
        """Record a purchase; returns the number of points earned."""
        if amount <= 0:
            raise ValueError("Purchase amount must be greater than zero.")

        points_earned = int(amount // 10)
        if customer not in self.customers:
            self.customers[customer] = {
                "purchases": [(amount, day)],
                "points": 0,
                "redeemed": 0
            }
        else:
            self.customers[customer]["purchases"].append((amount, day))

        return points_earned

    def balance(self, customer: str, day: date) -> int:
        """Points the customer can spend on the given day."""
        if customer not in self.customers:
            return 0

        available_points = 0
        for purchase in self.customers[customer]["purchases"]:
            points_earned = int(purchase[0] // 10)
            if day >= purchase[1] + timedelta(days=14):
                available_points += points_earned

        available_points -= self.customers[customer]["redeemed"]

        return available_points

    def redeem(self, customer: str, points: int, day: date) -> None:
        """Redeem points."""
        if points % 100 != 0:
            raise ValueError("Points can only be redeemed in multiples of 100.")

        if customer not in self.customers:
            raise ValueError("Customer has no points to redeem.")

        available_points = self.balance(customer, day)
        if points > available_points:
            raise ValueError("Customer does not have enough points to redeem.")

        self.customers[customer]["redeemed"] += points

# Example usage
if __name__ == "__main__":
    loyalty = Loyalty()
    print(loyalty.purchase("John", 100.0, date(2022, 1, 1)))  # Output: 10
    print(loyalty.balance("John", date(2022, 1, 1)))  # Output: 0
    print(loyalty.balance("John", date(2022, 1, 15)))  # Output: 10
    loyalty.redeem("John", 10, date(2022, 1, 15))  # Raises ValueError
    loyalty.redeem("John", 100, date(2022, 1, 15))  # Redeems 100 points
    print(loyalty.balance("John", date(2022, 1, 15)))  # Output: -90
```

